202| /** The fidelity judgment. The semantic call goes through the injected `invokeJudge` seam, but ONLY
203|  *  after the mechanical pre-filter (方向 B) fails to decide — the mechanical half short-circuits the
204|  *  LLM for the coverage-asymmetry cases (pre⇒vacuous, post⇒faithful) so the discrimination is
205|  *  deterministic and non-LLM. Returns { verdict, reason }. A thrown seam ⇒ not-evaluated (never
206|  *  faithful). */
207| export function criterionFidelityVerdict(
208|   criterion: string,
209|   expect: string,
210|   invokeJudge: FidelityInvokeJudge,
211|   opts: { root?: string; mechanism?: string } = {},
212| ): { verdict: FidelityVerdict; reason: string } {
213|   // 方向 B 机械前置筛（⛔ 不调 LLM）：机制源优先用注入的 `opts.mechanism`（测试/确定性路径），
214|   // 否则从 criterion 命令引用的检查器文件读回（生产激活路径）。
215|   const mechanism = opts.mechanism ?? readMechanismFromCriterion(criterion, opts.root);
216|   const mechanical = mechanicalFidelityVerdict(expect, mechanism);
217|   if (mechanical !== null) {
218|     return {
219|       verdict: mechanical,
220|       reason: mechanical === "vacuous"
221|         ? "mechanical fidelity (no LLM): a scanned source directory's path segment appears in no pattern — coverage gap ⇒ vacuous"
222|         : "mechanical fidelity (no LLM): every scanned source directory's path segment is covered by some pattern ⇒ faithful",
223|     };
224|   }
225|   const prompt = buildFidelityPrompt(criterion, expect, opts);
226|   let res: FidelityJudgeResult;
227|   try {
228|     res = invokeJudge(prompt);
229|   } catch (err) {
230|     return {
231|       verdict: "not-evaluated",
232|       reason: `fidelity judge threw: ${err instanceof Error ? err.message : String(err)}`,
233|     };
234|   }
235|   const verdict = parseFidelityVerdict(res.stdout, res.exitCode);
236|   const reason = verdict === "not-evaluated"
237|     ? `fidelity judge unreadable (exit ${res.exitCode})`
238|     : `fidelity judge: ${verdict}`;
239|   return { verdict, reason };
240| }

1302| /** 单次充分性语义采样（一次 LLM spawn）。⛔ 不可用 / 超时 / 读不懂 ⇒ not-evaluated，绝不回落 covered
1303|  *  （parseSemanticSufficiencyVerdict 的 fail-closed）。从 semanticSufficiencyVerdict 抽出，供「2 次一致
1304|  *  才入缓存」的一致性守卫对同一输入做两次独立采样。
1305|  *
1306|  *  AC3 成因（cause）：把 not-evaluated 拆成可区分的三种成因，⛔ 三者仍是 not-evaluated（不新增「合格」态）：
1307|  *  judge-unavailable（空命令 / launchArgv 失败 / spawn 失败 / 超时 / 非零退出）与 judge-unparseable
1308|  *  （exit 0 但输出不可解析）在此处按「判定器跑没跑通」区分，samples-disagree 由上层 2 次取样不一致产出。 */
1309| async function sampleSemanticSufficiency(
1310|   goal: Record<string, unknown>,
1311|   inScopeAcs: Array<Record<string, unknown>>,
1312|   root: string,
1313|   opts: { sufficiencyCmd?: string[] | null; sufficiencyTimeoutMs?: number },
1314| ): Promise<{ verdict: SufficiencyVerdict; cause: SufficiencyNotEvaluatedCause | null }> {
1315|   const prompt = buildSufficiencyPrompt(goal, inScopeAcs, root);
1316|   let argv: string[];
1317|   try {
1318|     if (opts.sufficiencyCmd != null) {
1319|       if (opts.sufficiencyCmd.length === 0) return { verdict: "not-evaluated", cause: "judge-unavailable" };
1320|       argv = [...opts.sufficiencyCmd, prompt];
1321|     } else {
1322|       argv = launchArgv("fix-worker", prompt, root);
1323|     }
1324|   } catch {
1325|     // launchArgv 抛错（profiles.yml 缺失/非法）⇒ 判不出，⛔ 不回落 covered。
1326|     return { verdict: "not-evaluated", cause: "judge-unavailable" };
1327|   }
1328|   const r = await runAsync(argv, { timeoutMs: opts.sufficiencyTimeoutMs ?? SUFFICIENCY_TIMEOUT_MS });
1329|   if (r.error) return { verdict: "not-evaluated", cause: "judge-unavailable" };
1330|   // 非零退出 = 判定器进程本身失败（未跑通）⇒ 不可用，⛔ 不是「输出不可解析」。
1331|   if (r.status !== 0) return { verdict: "not-evaluated", cause: "judge-unavailable" };
1332|   const parsed = parseSemanticSufficiencyVerdict(r.stdout, r.status);
1333|   if (parsed === "not-evaluated") return { verdict: "not-evaluated", cause: "judge-unparseable" };
1334|   return { verdict: parsed, cause: null };
1335| }

